SELECT TO_CHAR(a.att03_work_date, 'YYYY-MM-DD')
  FROM att03_overtime_req a
       INNER JOIN emp01_person ON emp01_person_id = a.att03_person_id
 WHERE a.att03_company_id = #{companyId}
   AND a.att03_person_id  = #{personId}
   AND #{yyyyMM} = TO_CHAR(a.att03_work_date, 'YYYYMM')

SELECT count(*)
  FROM att05_pm_work
       LEFT OUTER JOIN apr01_appr ON apr01_appr_id = att05_appr_id
 WHERE att05_company_id = #{companyId}
   AND att05_person_id  = #{personId}
   AND att05_work_date  = #{workDate}
   AND COALESCE(apr01_status_cd, '99') IN ('10', '20', '30')

